import {freshStudyIntent,cleanStudyIntent} from './study-intent.js?v=0.17.0';
import {freshReflection,cleanReflection} from './subject-reflection.js?v=0.17.0';
import {freshLifestyleDraft,cleanLifestyleDraft} from './lifestyle-state.js';
export const EARLIEST_STORAGE_KEY='fieldguide:approach-2:college-pathways:v1';
export const OLDER_STORAGE_KEY='fieldguide:approach-2:college-pathways:v2';
export const LEGACY_STORAGE_KEY='fieldguide:approach-2:college-pathways:v3';
export const STORAGE_KEY='fieldguide:approach-2:college-pathways:v4';
export const themeNames=['Hands-on building','Investigation & discovery','Creative expression','Helping & teaching','Leading & persuading','Organization & detail'];
export function freshDraft(){return{version:1,answers:{},sample:null,saved:[],activityId:null,choiceRevision:0,choices:{programs:[],careers:[]},notes:{},tasks:{},lifestyle:freshLifestyleDraft(),reflection:freshReflection(),studyIntent:freshStudyIntent()};}
export function cleanDraft(value,ids){const s=freshDraft();if(!value||value.version!==1)return s;for(const[k,v]of Object.entries(value.answers||{}))if(/^onet-sf-\d{2}$/.test(k)&&Number.isInteger(v)&&v>=1&&v<=5)s.answers[k]=v;s.sample=Array.isArray(value.sample?.raw)&&value.sample.raw.length===6&&value.sample.raw.every(v=>Number.isFinite(v)&&v>=0&&v<=40)?{name:String(value.sample.name||'Sample').slice(0,80),raw:value.sample.raw}:null;s.saved=[...new Set(Array.isArray(value.saved)?value.saved:[])].filter(id=>ids.includes(id)).slice(0,3);for(const id of ids){if(typeof value.notes?.[id]==='string')s.notes[id]=value.notes[id].slice(0,4000);for(const i of [0,1,2])if(value.tasks?.[id+':'+i]===true)s.tasks[id+':'+i]=true;}s.activityId=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(value.activityId||'')?value.activityId:null;s.choiceRevision=Number.isSafeInteger(value.choiceRevision)&&value.choiceRevision>=0?value.choiceRevision:0;for(const kind of ['programs','careers']){const seen=new Set();s.choices[kind]=(Array.isArray(value.choices?.[kind])?value.choices[kind]:[]).filter(x=>x&&ids.includes(x.pathId)&&(kind==='programs'?/^\d{2}\.\d{4}$/:/^\d{2}-\d{4}\.\d{2}$/).test(x.code)&&!seen.has(x.pathId+'|'+x.code)&&seen.add(x.pathId+'|'+x.code)).slice(0,24).map(x=>({pathId:x.pathId,code:x.code}));}s.lifestyle=cleanLifestyleDraft(value.lifestyle);s.reflection=cleanReflection(value.reflection);s.studyIntent=cleanStudyIntent(value.studyIntent,ids);return s;}
export function scorePathways(paths,profile){const raw=profile?.raw,valid=profile?.complete&&Array.isArray(raw)&&raw.length===6&&raw.every(Number.isFinite)&&!profile.flat&&!profile.nearFlat;
return paths.map(p=>{const weights=p.weights.map(w=>Math.max(0,w-1)),sum=weights.reduce((a,b)=>a+b,0);const score=valid?weights.reduce((n,w,i)=>n+w*raw[i],0)/sum:null;const reasons=valid?weights.map((w,i)=>({i,value:w*raw[i],name:themeNames[i]})).filter(x=>x.value>0).sort((a,b)=>b.value-a.value).slice(0,2).map(x=>x.name):[];return{...p,score,reasons};}).sort((a,b)=>valid?b.score-a.score||a.title.localeCompare(b.title):a.title.localeCompare(b.title));}
export function toggleSaved(s,id,ids){if(!ids.includes(id))return false;if(s.saved.includes(id)){s.saved=s.saved.filter(x=>x!==id);return true;}if(s.saved.length===3)return false;s.saved.push(id);return true;}
export function stageFor(o){if(o.stage==='further-study')return'Additional education or professional preparation';if(o.stage==='experience')return'Usually a destination after experience';if(o.stage==='qualifying-route')return'Check the specific program, training and entry requirements';if(o.stage==='unknown')return'Typical preparation unavailable; investigate the specific route';if(/Nurse Practitioners|Nurse Anesthetists|Nurse Midwives|Advanced Practice|Clinical Nurse Specialists|Physicians|Physician Assistants|Anesthesiologist Assistants|Dentists|Psychiatrists|Physical Therapists|Occupational Therapists|Psychologists|Lawyers|Veterinarians|Postsecondary|Computer and Information Research Scientists/i.test(o.title))return'Additional education or professional preparation';if(/Managers|Chief Executives|Directors|Administrators|Computer Network Architects/i.test(o.title))return'Usually a destination after experience';if(o.jobZone===5)return'Extensive preparation; check education, training and experience';return'Check the specific program and entry requirements';}
