export function careerExamples(path,occupations,program=null){const codes=program?path.programs.find(p=>p.cip===program)?.occupations||[]:path.occupations,preferred=featured[path.id]||[],rank=o=>preferred.includes(o.soc)?preferred.indexOf(o.soc):100;return codes.map(c=>occupations[c]).filter(Boolean).sort((a,b)=>rank(a)-rank(b)||Number(stageFor(a)!=='Check the specific program and entry requirements')-Number(stageFor(b)!=='Check the specific program and entry requirements')||a.title.localeCompare(b.title));}
